//! Local anisette on macOS, generated by the system's own AOSKit/AuthKit.
//!
//! [GatePass] Added because Apple started rejecting the outdated Mac identity
//! (macOS 10.12) advertised by public remote-anisette servers with HTTP 403 on
//! every `gsa.apple.com/auth*` call (see Impactor issue #305). Using the real
//! machine's identity makes Apple treat the login like a genuine Mac sign-in,
//! so the 2FA prompt is pushed to the user's trusted devices as usual.
#![cfg(target_os = "macos")]

use std::collections::HashMap;
use std::ffi::{CStr, CString, c_char};

use objc::runtime::{Class, Object};
use objc::{msg_send, sel, sel_impl};

use crate::AnisetteError;
use crate::anisette_headers_provider::AnisetteHeadersProvider;

const AOSKIT: &str = "/System/Library/PrivateFrameworks/AOSKit.framework/AOSKit";
const AUTHKIT: &str = "/System/Library/PrivateFrameworks/AuthKit.framework/AuthKit";
/// Routing info value used by AltServer for macOS-generated anisette.
const ROUTING_INFO: &str = "17106176";

pub struct AOSKitAnisetteProvider;

impl AOSKitAnisetteProvider {
    /// Fails (so callers can fall back to remote anisette) if the frameworks are unavailable.
    pub fn new() -> Result<Self, AnisetteError> {
        for path in [AOSKIT, AUTHKIT] {
            let c = CString::new(path).unwrap();
            if unsafe { libc::dlopen(c.as_ptr(), libc::RTLD_NOW) }.is_null() {
                return Err(AnisetteError::UnsupportedDevice);
            }
        }
        if Class::get("AOSUtilities").is_none() || Class::get("AKDevice").is_none() {
            return Err(AnisetteError::UnsupportedDevice);
        }
        let provider = Self;
        provider.collect()?; // make sure it actually produces data
        Ok(provider)
    }

    fn collect(&self) -> Result<HashMap<String, String>, AnisetteError> {
        objc::rc::autoreleasepool(|| unsafe {
            let utils = Class::get("AOSUtilities").ok_or(AnisetteError::UnsupportedDevice)?;
            let dsid = ns_string("-2");
            let otp: *mut Object = msg_send![utils, retrieveOTPHeadersForDSID: dsid];
            let md = dict_string(otp, "X-Apple-MD").ok_or(AnisetteError::AnisetteNotProvisioned)?;
            let md_m = dict_string(otp, "X-Apple-MD-M").ok_or(AnisetteError::AnisetteNotProvisioned)?;
            let serial_obj: *mut Object = msg_send![utils, machineSerialNumber];
            let serial = rust_string(serial_obj).unwrap_or_else(|| "0".into());

            let device_class = Class::get("AKDevice").ok_or(AnisetteError::UnsupportedDevice)?;
            let device: *mut Object = msg_send![device_class, currentDevice];
            let udid_obj: *mut Object = msg_send![device, uniqueDeviceIdentifier];
            let lu_obj: *mut Object = msg_send![device, localUserUUID];
            let desc_obj: *mut Object = msg_send![device, serverFriendlyDescription];
            let udid = rust_string(udid_obj).ok_or(AnisetteError::UnsupportedDevice)?;
            let local_user = rust_string(lu_obj).ok_or(AnisetteError::UnsupportedDevice)?;
            let client_info = rust_string(desc_obj)
                .ok_or(AnisetteError::UnsupportedDevice)?
                .replace("((null)/1.0)", "(com.apple.akd/1.0)");

            let mut headers = HashMap::new();
            headers.insert("X-Apple-I-MD".to_string(), md);
            headers.insert("X-Apple-I-MD-M".to_string(), md_m);
            headers.insert("X-Apple-I-MD-RINFO".to_string(), ROUTING_INFO.to_string());
            headers.insert("X-Apple-I-MD-LU".to_string(), local_user);
            headers.insert("X-Mme-Device-Id".to_string(), udid);
            headers.insert("X-Apple-I-SRL-NO".to_string(), serial);
            headers.insert("X-Mme-Client-Info".to_string(), client_info);
            headers.insert(
                "X-Apple-I-Client-Time".to_string(),
                chrono::Utc::now().format("%Y-%m-%dT%H:%M:%SZ").to_string(),
            );
            headers.insert("X-Apple-I-TimeZone".to_string(), "UTC".to_string());
            headers.insert("X-Apple-Locale".to_string(), "en_US".to_string());
            Ok(headers)
        })
    }
}

#[cfg_attr(feature = "async", async_trait::async_trait)]
impl AnisetteHeadersProvider for AOSKitAnisetteProvider {
    #[cfg_attr(not(feature = "async"), remove_async_await::remove_async_await)]
    async fn get_anisette_headers(
        &mut self,
        _skip_provisioning: bool,
    ) -> Result<HashMap<String, String>, AnisetteError> {
        self.collect()
    }
}

unsafe fn ns_string(s: &str) -> *mut Object {
    let class = Class::get("NSString").unwrap();
    let c = CString::new(s).unwrap();
    unsafe { msg_send![class, stringWithUTF8String: c.as_ptr()] }
}

unsafe fn rust_string(obj: *mut Object) -> Option<String> {
    if obj.is_null() {
        return None;
    }
    let ptr: *const c_char = unsafe { msg_send![obj, UTF8String] };
    if ptr.is_null() {
        return None;
    }
    Some(unsafe { CStr::from_ptr(ptr) }.to_string_lossy().into_owned())
}

unsafe fn dict_string(dict: *mut Object, key: &str) -> Option<String> {
    if dict.is_null() {
        return None;
    }
    unsafe {
        let k = ns_string(key);
        let value: *mut Object = msg_send![dict, objectForKey: k];
        rust_string(value)
    }
}
